/*
  DotFace — dotted-head talking-head rig for custom AI builds.

  Drop-in usage (script tag):
    <canvas id="my-face"></canvas>
    <script src="/face-rig.js"></script>
    <script>
      const face = new DotFace(document.getElementById('my-face'));
      // Wire to your AI's voice output:
      face.attachAudio(document.getElementById('aiAudio'));   // any HTMLMediaElement
      // ...or push amplitudes directly from your TTS pipeline:
      face.driveAmplitude(0.7);                              // 0..1
      // ...or just let it auto-animate:
      face.speak('Hello there.');                            // uses SpeechSynthesis
    </script>

  ESM usage:
    import { DotFace, FACE_DATA } from './face-rig.js';

  Public API:
    new DotFace(canvas, opts?)              // opts: { autoplay:true, data:FACE_DATA }
    .blink()                                 single blink, manual trigger
    .startTalking() / .stopTalking()         procedural mouth on/off
    .driveAmplitude(v01)                     manual mouth opening, 0..1, decays naturally
    .attachAudio(htmlMediaEl)                drive mouth from <audio>/<video> amplitude
    .attachMic()                             drive mouth from microphone (async, asks perm)
    .detachAudio()                           unhook audio source
    .speak(text, { rate, pitch, voice })     SpeechSynthesis + mouth in sync; returns Promise
    .setSway(bool)                           idle head movement on/off
    .setMood('warm'|'neutral'|'thinking')    brow bias
    .lookAt(dx, dy)                          gaze offset, -1..1
    .destroy()                               stop the rAF loop, detach audio

  Region constants (eyes/mouth/brows) live in _classify().
*/

