class DotFace {
  constructor(canvas, opts = {}) {
    if (!canvas) throw new Error('DotFace: canvas element required');
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.data = opts.data || FACE_DATA;
    this.N = this.data.norm;
    this.W = this.data.w; this.H = this.data.h;

    this.TAGS = { OTHER:0, LEYE:1, REYE:2, MOUTH_UP:3, MOUTH_LO:4, LBROW:5, RBROW:6 };
    this.tags = this._classify();
    this.regions = this._centroids();

    this.t0 = performance.now();
    this.sway = true;
    this.headAngle = 0;
    this.headOffset = {x:0,y:0};
    this.blinkPhase = 0;
    this.blinking = false;
    this.nextBlinkAt = this._scheduleBlink(performance.now());
    this.talking = false;
    this.talkAmp = 0;                  // smoothed 0..1
    this.driveTarget = 0;              // manual driveAmplitude target
    this.audio = { ctx:null, analyser:null, data:null, source:null, kind:null };
    this.mood = 'neutral';
    this.lookOffset = {x:0,y:0};
    this.gaze = {x:0,y:0};
    this.gazeTargetAt = performance.now() + 1200;
    this.browLift = 0;
    this.browTarget = 0;
    this.browTargetAt = performance.now() + 1800;
    this._alive = true;

    this._buildStaticLayer();
    this._onResize = () => this._resize();
    addEventListener('resize', this._onResize);
    this._resize();
    this._loop = this._loop.bind(this);
    requestAnimationFrame(this._loop);

    if (opts.autoplay) { this.startTalking(); }
  }

  destroy() {
    this._alive = false;
    removeEventListener('resize', this._onResize);
    this.detachAudio();
  }

  // ── Region tagging ────────────────────────────────────────────────────
  _classify() {
    const { x, y, count, norm } = this.data;
    const T = this.TAGS;
    const tags = new Uint8Array(count);
    // [x1,y1,x2,y2] in normalized source-image coords; tune in place.
    const R = {
      LEYE:  [0.265, 0.272, 0.380, 0.345],
      REYE:  [0.420, 0.272, 0.525, 0.345],
      MOUTH: [0.300, 0.490, 0.495, 0.580],
      LBROW: [0.250, 0.240, 0.390, 0.282],
      RBROW: [0.405, 0.240, 0.535, 0.282],
    };
    const MID_MOUTH = 0.535;
    const inR = (r, nx, ny) => nx >= r[0] && nx < r[2] && ny >= r[1] && ny < r[3];
    for (let i = 0; i < count; i++) {
      const nx = x[i]/norm, ny = y[i]/norm;
      if      (inR(R.LEYE,  nx, ny)) tags[i] = T.LEYE;
      else if (inR(R.REYE,  nx, ny)) tags[i] = T.REYE;
      else if (inR(R.MOUTH, nx, ny)) tags[i] = ny < MID_MOUTH ? T.MOUTH_UP : T.MOUTH_LO;
      else if (inR(R.LBROW, nx, ny)) tags[i] = T.LBROW;
      else if (inR(R.RBROW, nx, ny)) tags[i] = T.RBROW;
      else                            tags[i] = T.OTHER;
    }
    return tags;
  }

  _centroids() {
    const { x, y, count, norm } = this.data;
    const acc = new Map();
    for (const v of Object.values(this.TAGS)) acc.set(v, {sx:0, sy:0, n:0});
    for (let i = 0; i < count; i++) {
      const a = acc.get(this.tags[i]); a.sx += x[i]; a.sy += y[i]; a.n++;
    }
    const NAME = Object.entries(this.TAGS).reduce((m, [k,v]) => (m[v]=k, m), {});
    const out = {};
    for (const [v, a] of acc) {
      out[NAME[v]] = a.n ? { x: a.sx/a.n/norm, y: a.sy/a.n/norm, n: a.n } : null;
    }
    return out;
  }

  _buildStaticLayer() {
    const { x, y, r, count, norm } = this.data;
    const SCALE = 1200;
    const aspect = this.W / this.H;
    const cw = Math.round(SCALE * aspect), ch = SCALE;
    const c = document.createElement('canvas');
    c.width = cw; c.height = ch;
    const g = c.getContext('2d');
    g.fillStyle = '#000'; g.fillRect(0,0,cw,ch);
    g.fillStyle = 'rgba(0,225,255,0.18)';
    for (let i = 0; i < count; i++) {
      if (this.tags[i] !== this.TAGS.OTHER) continue;
      const cx = (x[i]/norm) * SCALE, cy = (y[i]/norm) * SCALE;
      const rr = Math.max(1.4, (r[i]/norm) * SCALE * 1.6);
      g.beginPath(); g.arc(cx, cy, rr, 0, Math.PI*2); g.fill();
    }
    g.fillStyle = '#7feeff';
    for (let i = 0; i < count; i++) {
      if (this.tags[i] !== this.TAGS.OTHER) continue;
      const cx = (x[i]/norm) * SCALE, cy = (y[i]/norm) * SCALE;
      const rr = Math.max(0.8, (r[i]/norm) * SCALE * 0.9);
      g.beginPath(); g.arc(cx, cy, rr, 0, Math.PI*2); g.fill();
    }
    this._static = c;
  }

  _resize() {
    const dpr = Math.min(devicePixelRatio || 1, 2);
    let w = this.canvas.clientWidth, h = this.canvas.clientHeight;
    if (!w || !h) { w = innerWidth; h = innerHeight; }
    this.canvas.width  = Math.max(2, Math.round(w * dpr));
    this.canvas.height = Math.max(2, Math.round(h * dpr));
    this.dpr = dpr;
    this.cssW = w; this.cssH = h;
  }

  // ── Public API ────────────────────────────────────────────────────────
  blink() { if (!this.blinking) { this.blinking = true; this._blinkT0 = performance.now(); } }
  startTalking() { this.talking = true; }
  stopTalking()  { this.talking = false; }
  setSway(on)    { this.sway = !!on; }
  setMood(m)     { this.mood = m; }
  lookAt(dx, dy) { this.lookOffset.x = dx; this.lookOffset.y = dy; }

  // External amplitude push (e.g. from your TTS pipeline's audio worklet).
  // Decays naturally between calls — call it ~30-60Hz for smooth mouth.
  driveAmplitude(v) {
    this.driveTarget = Math.max(0, Math.min(1, v || 0));
    if (this.driveTarget > 0.02) this.talking = true;
  }

  attachAudio(el) { return this._attachSource('media', el); }
  async attachMic() {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      return this._attachSource('stream', stream);
    } catch (e) { return false; }
  }
  detachAudio() {
    if (this.audio.ctx) { try { this.audio.ctx.close(); } catch(_){} }
    this.audio = { ctx:null, analyser:null, data:null, source:null, kind:null };
  }
  _attachSource(kind, src) {
    this.detachAudio();
    const ACtx = window.AudioContext || window.webkitAudioContext;
    if (!ACtx) return false;
    const ctx = new ACtx();
    const an = ctx.createAnalyser(); an.fftSize = 512; an.smoothingTimeConstant = 0.6;
    const data = new Uint8Array(an.frequencyBinCount);
    let node;
    if (kind === 'media') {
      node = ctx.createMediaElementSource(src);
      node.connect(an); an.connect(ctx.destination);
    } else {
      node = ctx.createMediaStreamSource(src);
      node.connect(an);
    }
    this.audio = { ctx, analyser: an, data, source: node, kind };
    this.startTalking();
    return true;
  }

  // Speak text via browser SpeechSynthesis with the mouth in sync.
  // Returns a Promise that resolves when speech ends.
  // Note: Web Speech doesn't expose its audio for amplitude analysis, so
  // the mouth is driven procedurally (with boundary-event punch) — for
  // tight lip-sync, route your TTS through an <audio> element + attachAudio.
  speak(text, opts = {}) {
    if (!('speechSynthesis' in window)) return Promise.reject(new Error('no SpeechSynthesis'));
    return new Promise((resolve) => {
      const u = new SpeechSynthesisUtterance(String(text || ''));
      if (opts.rate)  u.rate  = opts.rate;
      if (opts.pitch) u.pitch = opts.pitch;
      if (opts.voice) u.voice = opts.voice;
      u.onstart = () => this.startTalking();
      // Each word boundary kicks the amplitude up so the mouth has rhythm.
      u.onboundary = () => { this.talkAmp = Math.min(1, this.talkAmp + 0.55); };
      u.onend = () => { this.stopTalking(); resolve(); };
      u.onerror = () => { this.stopTalking(); resolve(); };
      speechSynthesis.speak(u);
    });
  }

  // ── Internal frame logic ──────────────────────────────────────────────
  _scheduleBlink(now) { return now + 1800 + Math.random() * 2800; }

  _step(now) {
    const t = (now - this.t0) / 1000;

    if (this.sway) {
      const tk = this.talking ? 1.7 : 1.0;
      this.headAngle    = (Math.sin(t * 0.55) * 0.045 + Math.sin(t * 0.23 + 1) * 0.022) * tk;
      this.headOffset.x = (Math.sin(t * 0.35) * 14 + Math.sin(t * 0.17 + 0.5) * 7) * tk;
      this.headOffset.y = (Math.sin(t * 0.62 + 0.7) * 9 + Math.sin(t * 0.27) * 4) * tk;
    } else {
      this.headAngle *= 0.9; this.headOffset.x *= 0.9; this.headOffset.y *= 0.9;
    }

    if (!this.blinking && now >= this.nextBlinkAt) {
      this.blink();
      if (Math.random() < 0.22) setTimeout(() => this.blink(), 220);
      this.nextBlinkAt = this._scheduleBlink(now);
    }
    if (this.blinking) {
      const bt = now - this._blinkT0;
      if (bt < 130)      this.blinkPhase = bt / 130;
      else if (bt < 290) this.blinkPhase = 1 - (bt - 130) / 160;
      else { this.blinking = false; this.blinkPhase = 0; }
    }

    // Mouth amplitude resolution order:
    //   1) audio analyser RMS (if attached)
    //   2) external driveAmplitude() push
    //   3) procedural speech envelope (if talking)
    if (this.audio.analyser) {
      this.audio.analyser.getByteFrequencyData(this.audio.data);
      let s = 0, n = 0;
      const lo = 4, hi = Math.min(80, this.audio.data.length);
      for (let i = lo; i < hi; i++) { const v = this.audio.data[i] / 255; s += v*v; n++; }
      const rms = Math.sqrt(s / Math.max(1, n));
      this.talkAmp = Math.min(1, this.talkAmp * 0.55 + rms * 2.0 * 0.45);
    } else if (this.driveTarget > 0) {
      this.talkAmp = this.talkAmp * 0.6 + this.driveTarget * 0.4;
      this.driveTarget *= 0.85;  // decay so a single push doesn't stick
    } else if (this.talking) {
      const carrier = (Math.sin(t * 12) * 0.5 + 0.5);
      const phrase  = Math.max(0, Math.sin(t * 1.4) * 0.5 + 0.55);
      const target  = carrier * phrase;
      this.talkAmp = this.talkAmp * 0.45 + target * 0.55;
    } else {
      this.talkAmp *= 0.78;
    }

    if (now >= this.gazeTargetAt) {
      this.gaze.x = (Math.random() * 2 - 1) * 0.7;
      this.gaze.y = (Math.random() * 2 - 1) * 0.5;
      this.gazeTargetAt = now + 1200 + Math.random() * 1800;
    }
    this.lookOffset.x += (this.gaze.x - this.lookOffset.x) * 0.06;
    this.lookOffset.y += (this.gaze.y - this.lookOffset.y) * 0.06;

    if (now >= this.browTargetAt) {
      this.browTarget = (Math.random() * 2 - 1) * 3.0;
      this.browTargetAt = now + 1800 + Math.random() * 2400;
    }
    const moodBias = this.mood === 'warm' ? -2 : this.mood === 'thinking' ? 2 : 0;
    this.browLift += ((this.browTarget + moodBias) - this.browLift) * 0.06;
  }

  _loop(now) {
    if (!this._alive) return;
    this._step(now);
    this._draw();
    requestAnimationFrame(this._loop);
  }

  _draw() {
    const ctx = this.ctx, dpr = this.dpr;
    const W = this.cssW, H = this.cssH;
    if (!W || !H) return;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = '#000'; ctx.fillRect(0, 0, W, H);

    const margin = 0.04;
    const faceAspect = this.W / this.H;
    let drawH = H * (1 - margin*2);
    let drawW = drawH * faceAspect;
    if (drawW > W * (1 - margin*2)) { drawW = W * (1 - margin*2); drawH = drawW / faceAspect; }
    const cx = W / 2, cy = H / 2;
    const faceCx = 0.397, faceCy = 0.49;
    const scaleX = drawW / this.W;
    const scaleY = drawH / this.H;

    ctx.save();
    ctx.translate(cx + this.headOffset.x, cy + this.headOffset.y);
    ctx.rotate(this.headAngle);
    ctx.drawImage(this._static, -faceCx * drawW, -faceCy * drawH, drawW, drawH);

    const T = this.TAGS;
    const { x, y, r, count } = this.data;
    const toX = (sx) => sx * scaleX - faceCx * drawW;
    const toY = (sy) => sy * scaleY - faceCy * drawH;

    const eyeC = {
      L: { x: this.regions.LEYE.x * this.W, y: this.regions.LEYE.y * this.H },
      R: { x: this.regions.REYE.x * this.W, y: this.regions.REYE.y * this.H },
    };
    const blink = this.blinkPhase;
    const talk  = this.talkAmp * (this.H * 0.022);
    const tNow = (performance.now() - this.t0) / 1000;
    const saccadeX = this.lookOffset.x * 7 + Math.sin(tNow * 0.7) * 1.5;
    const saccadeY = this.lookOffset.y * 5 + Math.cos(tNow * 0.9) * 1.0;
    const browLift = this.browLift;

    const passes = [
      { fill: 'rgba(0,225,255,0.18)', mul: 1.6 },
      { fill: '#7feeff',              mul: 0.9 },
    ];
    for (const pass of passes) {
      ctx.fillStyle = pass.fill;
      for (let i = 0; i < count; i++) {
        const tag = this.tags[i];
        if (tag === T.OTHER) continue;
        let sx = x[i], sy = y[i];
        if (tag === T.LEYE || tag === T.REYE) {
          const c = (tag === T.LEYE) ? eyeC.L : eyeC.R;
          sy = c.y + (sy - c.y) * (1 - blink * 0.95);
          if (Math.abs(sy - c.y) < 8) { sx += saccadeX; sy += saccadeY; }
        } else if (tag === T.MOUTH_UP) {
          sy -= talk * 0.6;
        } else if (tag === T.MOUTH_LO) {
          sy += talk * 1.0;
        } else if (tag === T.LBROW || tag === T.RBROW) {
          sy += browLift;
        }
        const px = toX(sx), py = toY(sy);
        const rr = Math.max(0.7, r[i] * Math.min(scaleX, scaleY) * pass.mul);
        ctx.beginPath(); ctx.arc(px, py, rr, 0, Math.PI*2); ctx.fill();
      }
    }
    ctx.restore();
  }
}

// Expose for classic <script> tag use. AI frontends overwhelmingly use this
// pattern; for ESM, dynamic-import this file and read globalThis.DotFace.
if (typeof window !== 'undefined') { window.DotFace = DotFace; window.FACE_DATA = FACE_DATA; }
if (typeof module !== 'undefined' && module.exports) { module.exports = { DotFace, FACE_DATA }; }
